MOD = 998244353
n = int(input())
p = list(map(lambda x: int(x) - 1, input().split()))
s = list(input())
sp = [True for i in range(n)]
valid_configurations = 1

for i in p:
    left_spoon = i
    right_spoon = (i + 1) % n

    if sp[left_spoon] and sp[right_spoon]:
        if s[i] == 'L':
            sp[left_spoon] = False
        elif s[i] == 'R':
            sp[right_spoon] = False
        elif s[i] == '?':
            valid_configurations *= 2
            valid_configurations %= MOD
            sp[left_spoon] = False
    elif sp[left_spoon]:
        sp[left_spoon] = False
    elif sp[right_spoon]:
        sp[right_spoon] = False
    else:
        valid_configurations = 0
        break

print(valid_configurations)
